/* ============================================================ Gambar (SVG inline)
   Logo, dua maskot, ilustrasi greenhouse, ikon, dan foto contoh kamera kebun.
   Semua bentuk dibuat dari lingkaran dan kurva sederhana supaya tajam di semua ukuran. */
const WARNA = { mint: '#8EEDC7', hijau: '#046B37', peach: '#F5BFA0', krem: '#FDF5EE' };
let _uid = 0;
const uid = (p) => `${p}${++_uid}`;

// Kelopak semanggi (dalam kotak 100 x 100): dua atas, dua samping, dua bawah, satu tengah.
const KELOPAK = [[35.65, 25.2, 15.2], [64.35, 25.2, 15.2], [21.2, 51.1, 16], [78.8, 51.1, 16], [34.7, 76.9, 15], [65.6, 76.9, 15], [50, 52, 24]];
const GELOMBANG_A = 'M-2,58 C8,63 14,64.5 18,63.5 C26,61.5 32,55 38,48 C43,42.5 46.5,40.8 50,40.8 C53.5,40.8 57,42.5 62,48 C68,55 74,61.5 82,63.5 C86,64.5 92,63 102,58 L102,104 L-2,104 Z';
const LUBANG_A = 'M50,44.5 C46.5,44.5 44,47 41.5,50.5 C39,54 36.5,58 35.8,60.5 C35,63.5 37.3,65.6 40.3,65.4 C42.6,65.2 44,63.6 45.5,62.8 C47,62 48.6,61.8 50,61.8 C51.4,61.8 53,62 54.5,62.8 C56,63.6 57.4,65.2 59.7,65.4 C62.7,65.6 65,63.5 64.2,60.5 C63.5,58 61,54 58.5,50.5 C56,47 53.5,44.5 50,44.5 Z';
const kelopak = (fill) => KELOPAK.map(([x, y, r]) => `<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}"/>`).join('');

/** Simbol logo AgroSync (semanggi + huruf A). */
function logoSimbol() {
  const k = uid('lk');
  return `<defs><clipPath id="${k}">${kelopak('#000')}</clipPath></defs>
    <g>${kelopak(WARNA.mint)}</g>
    <path d="${GELOMBANG_A}" fill="${WARNA.hijau}" clip-path="url(#${k})"/>
    <path d="${LUBANG_A}" fill="${WARNA.mint}"/>`;
}
function logoSVG(cls = '', label = 'AgroSync') {
  return `<svg class="${cls}" viewBox="4 8 92 86" role="img" aria-label="${label}" xmlns="http://www.w3.org/2000/svg">${logoSimbol()}</svg>`;
}

