/* ------------------------------------------------------------ Ilustrasi hero (greenhouse) */
function seladaRak(x, y, s = 1) {
  return `<g transform="translate(${x} ${y}) scale(${s})">
    <ellipse cx="0" cy="0" rx="14" ry="7" class="f-daun-tua"/><ellipse cx="-7" cy="-4" rx="8" ry="7" class="f-daun"/>
    <ellipse cx="7" cy="-4" rx="8" ry="7" class="f-daun"/><ellipse cx="0" cy="-7" rx="7.5" ry="6.5" class="f-daun-muda"/></g>`;
}
function rak(x, flip = false) {
  const tx = flip ? `translate(${x} 0) scale(-1 1)` : `translate(${x} 0)`;
  let s = '';
  for (const [y, n] of [[188, 3], [244, 3]]) for (let i = 0; i < n; i++) s += seladaRak(18 + i * 30, y - 6, .95);
  return `<g transform="${tx}">
    <rect x="12" y="190" width="7" height="140" rx="3" class="f-rangka"/><rect x="92" y="190" width="7" height="140" rx="3" class="f-rangka"/>
    <rect x="-2" y="186" width="114" height="12" rx="6" class="f-rak"/><rect x="-2" y="242" width="114" height="12" rx="6" class="f-rak"/>
    ${s}</g>`;
}
function bunga(x, y, s = 1) {
  return `<g transform="translate(${x} ${y}) scale(${s})"><path d="M0 0 C-2 10 -1 18 0 26" class="s-daun" fill="none" stroke-width="2.4"/>
    <ellipse cx="-7" cy="16" rx="6" ry="3" class="f-daun" transform="rotate(-30 -7 16)"/>
    <g class="f-peach"><circle cx="0" cy="-6" r="4.6"/><circle cx="5.7" cy="-1.8" r="4.6"/><circle cx="3.5" cy="4.9" r="4.6"/><circle cx="-3.5" cy="4.9" r="4.6"/><circle cx="-5.7" cy="-1.8" r="4.6"/></g>
    <circle cx="0" cy="0" r="2.6" fill="#fff"/></g>`;
}
function awan(x, y, s, kelas) {
  return `<g class="awan ${kelas}"><g transform="translate(${x} ${y}) scale(${s})"><path d="M0 40 C0 22 16 12 30 16 C36 2 60 -4 74 10 C88 2 110 10 110 30 C124 30 132 40 128 50 H4 C-2 50 -2 44 0 40Z" fill="#FFFFFF" opacity=".85"/></g></g>`;
}
function daunTerbang(i) {
  const x = [140, 260, 420, 560, 700, 840, 980, 1090][i], warna = ['#8EEDC7', '#A5DC74', '#6CC04A', '#F5BFA0'][i % 4];
  return `<g class="daun-terbang" style="--x:${x}px;--d:${9 + (i * 1.7) % 7}s;--t:${-i * 1.9}s"><path d="M0 0 C8 -10 22 -10 26 0 C22 10 8 10 0 0Z" fill="${warna}"/><path d="M2 0 H22" stroke="#fff" stroke-width="1.2" opacity=".6"/></g>`;
}
function kilauBintang(x, y, s, d) {
  return `<g transform="translate(${x} ${y}) scale(${s})"><path class="kilau" style="--d:${d}s" d="M0 -12 C1.5 -3 3 -1.5 12 0 C3 1.5 1.5 3 0 12 C-1.5 3 -3 1.5 -12 0 C-3 -1.5 -1.5 -3 0 -12Z" fill="#FFE27A"/></g>`;
}
function gelembungSapa(id, x, y, teks, w) {
  return `<g id="${id}" class="sapa" style="transform-box:fill-box;transform-origin:50% 100%">
    <rect x="${x - w / 2}" y="${y - 54}" width="${w}" height="48" rx="24" fill="#FFFFFF"/>
    <path d="M${x - 10} ${y - 8} L${x} ${y + 8} L${x + 8} ${y - 8}Z" fill="#FFFFFF"/>
    <text x="${x}" y="${y - 23}" text-anchor="middle" font-family="Poppins, 'Segoe UI', sans-serif" font-weight="700" font-size="24" fill="#046B37">${teks}</text></g>`;
}
function heroSVG() {
  let ledak = '';
  for (let i = 0; i < 12; i++) {
    const a = i / 12 * 360;
    ledak += `<g class="serpih" style="--a:${a}deg"><path d="M0 0 C6 -8 16 -8 20 0 C16 8 6 8 0 0Z" fill="${['#8EEDC7', '#6CC04A', '#F5BFA0', '#A5DC74'][i % 4]}"/></g>`;
  }
  let sinar = '';
  for (let i = 0; i < 10; i++) sinar += `<rect x="-4" y="-86" width="8" height="22" rx="4" fill="#FFD66B" transform="rotate(${i * 36})"/>`;
  return `<svg class="adegan-intro" id="intro-svg" viewBox="0 0 1200 560" preserveAspectRatio="xMidYMid slice" role="img" aria-labelledby="intro-judul" xmlns="http://www.w3.org/2000/svg">
    <title id="intro-judul">Ago dan Tata menyapa “Hai!”, lalu menyatu menjadi logo AgroSync</title>
    <g class="lapis" data-d=".12"><g transform="translate(1040 104)"><circle r="50" fill="#FFE27A" opacity=".35"/><g class="sinar">${sinar}</g><circle r="40" fill="#FFD66B"/></g>
    ${awan(150, 70, 1, 'awan-1')}${awan(820, 40, .8, 'awan-2')}${awan(470, 120, .55, 'awan-3')}</g>
    <g class="lapis" data-d=".3">
    <g fill="none" class="s-rangka" stroke-linecap="round">
      <path d="M70 560 C70 200 320 26 600 26 C880 26 1130 200 1130 560" stroke-width="12"/>
      <path d="M170 560 C170 260 360 110 600 110 C840 110 1030 260 1030 560" stroke-width="7" opacity=".6"/>
    </g>
    <g class="s-rangka" stroke-width="5" opacity=".45" fill="none"><path d="M600 26V110M330 120l60 46M870 120l-60 46M130 300l70 12M1070 300l-70 12"/></g></g>
    <g class="lapis" data-d=".45">
    <path d="M0 410 C140 360 280 372 420 392 C560 412 700 372 860 368 C980 366 1100 386 1200 398 V560 H0Z" class="f-bukit-1"/></g>
    <g class="lapis" data-d=".58">${rak(64)}${rak(1136, true)}</g>
    <g class="lapis" data-d=".75">
    <path d="M0 452 C170 426 330 436 480 452 C640 470 800 432 960 438 C1060 442 1140 450 1200 456 V560 H0Z" class="f-bukit-2"/>
    <ellipse cx="600" cy="486" rx="330" ry="22" class="f-bukit-3" opacity=".55"/>
    <path d="M0 506 C200 488 360 494 600 506 C820 518 1000 492 1200 500 V560 H0Z" class="f-bukit-3"/>
    ${bunga(110, 466, 1.2)}${bunga(172, 484, .9)}${bunga(1060, 468, 1.2)}${bunga(1112, 486, .85)}${bunga(952, 490, .8)}${bunga(262, 494, .75)}
    <defs><linearGradient id="h-pudar" x1="0" y1="0" x2="0" y2="1"><stop offset="0" style="stop-color:var(--hero-dasar);stop-opacity:0"/><stop offset=".45" style="stop-color:var(--hero-dasar);stop-opacity:.7"/><stop offset=".64" style="stop-color:var(--hero-dasar);stop-opacity:1"/><stop offset="1" style="stop-color:var(--hero-dasar);stop-opacity:1"/></linearGradient></defs>
    <rect x="-10" y="390" width="1220" height="172" fill="url(#h-pudar)"/></g>
    <g class="lapis" data-d=".9"><g class="daun-lapis">${Array.from({ length: 8 }, (_, i) => daunTerbang(i)).join('')}</g></g>
    <g class="lapis" data-d="1">
    <g id="h-logo" style="transform-box:fill-box;transform-origin:center">
      <g transform="translate(515 102) scale(1.7)">${logoSimbol()}</g>
    </g>
    <text id="h-kata" x="600" y="342" text-anchor="middle" font-family="Poppins, 'Segoe UI', sans-serif" font-weight="700" font-size="66" class="f-wordmark" letter-spacing="-1.5">AgroSync</text>
    <g id="h-kilau">${kilauBintang(485, 118, 1.2, 0)}${kilauBintang(720, 92, .9, .8)}${kilauBintang(735, 250, 1.1, 1.6)}${kilauBintang(470, 262, .8, 2.4)}</g>
    <g id="h-ledak" transform="translate(600 190)" opacity="0"><circle class="cincin-ledak" r="60" fill="none" stroke="#8EEDC7" stroke-width="6"/>${ledak}</g>
    <g id="h-siA" style="transform-box:fill-box;transform-origin:center"><g class="h-idle h-idle-a"><g class="langkah-a"><g transform="translate(277.5 330) scale(1.25)">${siAIsi('lambai')}</g></g></g></g>
    <g id="h-semanggi" style="transform-box:fill-box;transform-origin:center"><g class="h-idle h-idle-s"><g class="langkah-s"><g transform="translate(765 327) scale(1.25)">${semanggiIsi('lambai')}</g></g></g></g>
    ${gelembungSapa('h-sapa-a', 372, 316, 'Hai!', 110)}
    ${gelembungSapa('h-sapa-s', 850, 266, 'Selamat datang!', 228)}
    </g>
  </svg>`;
}

