/* ------------------------------------------------------------ Foto contoh kamera kebun (pakcoy dari atas) */
function fotoPakcoySVG(baru = true) {
  const g = uid('fg'), v = uid('fv');
  let daun = '';
  const n = 9;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * 360 + (baru ? 8 : 0);
    const kuning = i === 2 || i === 6;
    daun += `<g transform="rotate(${a} 160 120)"><ellipse cx="160" cy="70" rx="26" ry="46" fill="${kuning ? '#C9C24A' : (i % 2 ? '#3E9A3A' : '#5DBB46')}"/>
      <path d="M160 116 L160 34" stroke="${kuning ? '#E6DF8A' : '#C9EBA8'}" stroke-width="5" stroke-linecap="round"/></g>`;
  }
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * 360 + 30;
    daun += `<g transform="rotate(${a} 160 120)"><ellipse cx="160" cy="92" rx="15" ry="26" fill="#7BCB55"/><path d="M160 118 L160 72" stroke="#D9F2BF" stroke-width="3.5" stroke-linecap="round"/></g>`;
  }
  return `<svg viewBox="0 0 320 240" aria-hidden="true" preserveAspectRatio="xMidYMid slice">
    <defs><radialGradient id="${g}" cx="50%" cy="50%" r="70%"><stop offset="0" stop-color="#3B4A3F"/><stop offset="1" stop-color="#1A221C"/></radialGradient>
    <radialGradient id="${v}" cx="50%" cy="50%" r="75%"><stop offset=".6" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".55"/></radialGradient></defs>
    <rect width="320" height="240" fill="url(#${g})"/>
    <g opacity=".35" fill="#E9F0EA"><circle cx="34" cy="30" r="16"/><circle cx="290" cy="40" r="16"/><circle cx="30" cy="214" r="16"/><circle cx="292" cy="210" r="16"/></g>
    <circle cx="160" cy="120" r="34" fill="#151B16"/>
    ${daun}
    <circle cx="160" cy="120" r="9" fill="#E3F5C8"/>
    <rect width="320" height="240" fill="url(#${v})"/>
    <rect x="232" y="12" width="76" height="24" rx="6" fill="rgba(0,0,0,.55)"/><text x="270" y="29" text-anchor="middle" font-family="Inter, sans-serif" font-weight="700" font-size="13" fill="#fff" letter-spacing="1.5">CONTOH</text>
  </svg>`;
}
